const UI_THEME_KEY='pn-weekly-ui-theme-v1';
const uiThemeOptions={emerald:'มรกต–ทอง',ocean:'น้ำเงินกรมท่า',slate:'เทาเรียบหรู'};
function readUiTheme(){try{const value=JSON.parse(localStorage.getItem(UI_THEME_KEY)||'{}');return{theme:uiThemeOptions[value.theme]?value.theme:'emerald',mode:['light','dark','system'].includes(value.mode)?value.mode:'light',fontSize:[14,16,18].includes(+value.fontSize)?+value.fontSize:16,motion:value.motion!==false};}catch{return{theme:'emerald',mode:'light',fontSize:16,motion:true};}}
function applyUiTheme(value=readUiTheme()){const root=document.documentElement;root.dataset.uiFont=String(value.fontSize||16);root.dataset.uiMotion=value.motion===false?'off':'on';root.dataset.uiTheme=value.theme;root.dataset.uiMode=value.mode;root.style.colorScheme=value.mode==='dark'?'dark':value.mode==='system'?'light dark':'light';}
