function settings(){const cloudText=cloudMode?'🟢 เชื่อมต่อ Supabase แล้ว':cloud.config()?'🟡 ออฟไลน์ · มีการตั้งค่า Cloud':'⚪ โหมดบนเครื่อง (Local)';const outboxText=outbox.length?`📦 มีงานรอส่ง ${outbox.length} รายการ`:'✓ ส่งข้อมูลครบถ้วน';return header('ตั้งค่าระบบ','ตั้งค่ารายงาน สำรองข้อมูล และเชื่อมต่อ Supabase')+`<div class="grid2">${themeSettingsCard()}<div class="card settings-section"><h2>ข้อมูลระบบ</h2><form id="settings-form"><div class="form-grid" style="margin-top:20px">${field('หน่วยงาน','organization',state.settings.organization,'text','required')}${field('ชื่อระบบ','systemName',state.settings.systemName,'text','required')}<label class="field">โลโก้ PNG (ไม่เกิน 500 KB)<input id="logo-file" type="file" accept="image/png"><span class="hint">ใช้ทั้งหน้าเว็บและไอคอนแท็บ</span></label>${state.settings.logo?`<div class="field"><img src="${state.settings.logo}" alt="โลโก้ปัจจุบัน" style="width:64px;height:64px;object-fit:contain"><label><input type="checkbox" name="removeLogo"> ลบโลโก้</label></div>`:''}</div><div class="settings-footer"><div class="sync-info"><span>${cloudText}</span> · <span>${outboxText}</span></div><div class="dialog-actions"><button class="btn primary" type="submit">บันทึกการตั้งค่า</button></div></div></form></div><details class="card backup-settings"><summary>สำรองและกู้คืนขั้นสูง</summary><p class="sub">สำรองทะเบียนสัญญา รายงานทุกสัปดาห์ และประวัติ เป็น JSON</p><div class="actions"><button class="btn" data-action="backup">↓ สำรองข้อมูลทั้งหมด</button><button class="btn primary" data-action="restore">↑ นำเข้าข้อมูล JSON</button></div><p class="hint">ข้อมูลปัจจุบัน ${state.projects.length} สัญญา และ ${state.reports.filter(r=>r.id!=='EMPTY').length} รายงาน • ไฟล์สำรองมีข้อมูลจริง ควรเก็บในพื้นที่ที่จำกัดสิทธิ์</p></details></div>`;}
