function mountOperationalDock(){
 document.querySelector('.topbar .page-primary-actions')?.remove();
 headerMirror?.remove();headerMirror=null;operationalResizeObserver?.disconnect();
 const app=$('#app'),sources=[...app.querySelectorAll('.period-bar>.actions,.page-heading>.actions,.basic-data .table-top>.actions')].filter(el=>el.children.length),batch=app.querySelector('.weekly-batch-tools');
 const dock=document.createElement('div');dock.className='operational-dock';dock.setAttribute('aria-label','คำสั่งหลัก');
 for(const source of sources)for(const child of [...source.children])dock.append(child);
 if(batch)dock.prepend(batch);
 // Move secondary commands into one disclosure; the existing button nodes/handlers survive.
 const secondary=document.createElement('details');secondary.className='command-menu operational-more';secondary.innerHTML='<summary class="btn">เครื่องมือเพิ่มเติม</summary><div class="command-menu-panel"></div>';const menuView=view;secondary.open=operationalMenuState.get(menuView)||false;secondary.ontoggle=()=>operationalMenuState.set(menuView,secondary.open);
 for(const child of [...dock.children])if(!child.matches('.primary,.weekly-batch-tools,details')&&!child.querySelector('.primary'))secondary.lastElementChild.append(child);
 if(secondary.lastElementChild.children.length)dock.append(secondary);
 const settingsSave=app.querySelector('#settings-form [type=submit]');if(settingsSave){const shortcut=settingsSave.cloneNode(true);shortcut.setAttribute('form','settings-form');dock.append(shortcut);}if(dock.children.length){app.querySelector('.page-heading')?.after(dock);operationalDock=dock;}else operationalDock=null;
 for(const source of sources)if(!source.children.length)source.remove();
 // Put the weekly archival CTA beside Save, not inside a hidden menu.
 if(view==='weekly'){const primary=app.querySelector('[data-action=lock]');if(primary&&operationalDock){const shortcut=primary.cloneNode(true);shortcut.removeAttribute('data-action');shortcut.dataset.dockArchive='true';shortcut.classList.add('primary');shortcut.onclick=()=>withButtonLock(shortcut,()=>primary.onclick?.(),e=>toast(e.message,true));operationalDock.append(shortcut);}}
 let eyebrow=$('.executive-eyebrow');if(!eyebrow){eyebrow=document.createElement('small');eyebrow.className='executive-eyebrow';eyebrow.textContent='EXECUTIVE OVERVIEW';$('#crumb').before(eyebrow);}eyebrow.hidden=view!=='dashboard';
 if(view==='dashboard'){const target=app.querySelector('.dashboard-search-field'),input=app.querySelector('#search');if(target&&input)target.append(input.closest('.search-field')||input);}
 operationalResizeObserver=new ResizeObserver(scheduleOperationalLayout);for(const el of [operationalDock,$('.topbar'),...app.querySelectorAll('.table-scroll')])if(el)operationalResizeObserver.observe(el);
 scheduleOperationalLayout();
}
function layoutOperationalChrome(){
 const topbar=$('.institutional-header')||$('.topbar'),shell=Math.max(0,topbar?.getBoundingClientRect().bottom||0);document.documentElement.style.setProperty('--operational-shell-top',shell+'px');
 const dock=operationalDock?.isConnected?operationalDock:null,dockBottom=dock?Math.max(shell,dock.getBoundingClientRect().bottom):shell;
 document.documentElement.style.setProperty('--operational-header-top',dockBottom+'px');
 const candidates=innerWidth>640?[...$('#app').querySelectorAll('table')].filter(t=>operationalTable(t)&&!t.closest('[hidden]')&&t.getBoundingClientRect().top<dockBottom+(t.tHead?.getBoundingClientRect().height||0)&&t.getBoundingClientRect().bottom>dockBottom+(t.tHead?.getBoundingClientRect().height||0)):[];
 const table=candidates[0];if(!table){headerMirror?.source?.classList.remove('sticky-head-docked');headerMirror?.remove();headerMirror=null;return;}
 const scroll=table.closest('.table-scroll')||table.parentElement,clip=scroll.getBoundingClientRect(),rect=table.getBoundingClientRect();
 if(headerMirror?.source!==table){headerMirror?.source?.classList.remove('sticky-head-docked');headerMirror?.remove();headerMirror=document.createElement('div');headerMirror.className='operational-table-head';headerMirror.source=table;table.classList.add('sticky-head-docked');headerMirror.setAttribute('aria-label','หัวตารางตรึง');document.body.append(headerMirror);}
 const signature=table.tHead.innerHTML+'|'+[...table.tHead.rows].flatMap(r=>[...r.cells]).map(c=>c.getBoundingClientRect().width).join(',');if(headerMirror.signature!==signature){headerMirror.signature=signature;const head=table.tHead.cloneNode(true);head.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));const orig=[...table.tHead.rows].flatMap(r=>[...r.cells]),copy=[...head.rows].flatMap(r=>[...r.cells]);copy.forEach((cell,i)=>{const width=orig[i].getBoundingClientRect().width;cell.style.width=width+'px';cell.style.minWidth=width+'px';cell.style.maxWidth=width+'px';cell.style.position='static';const originalInputs=[...orig[i].querySelectorAll('button,input')];[...cell.querySelectorAll('button,input')].forEach((el,j)=>{el.onclick=e=>{e.preventDefault();originalInputs[j]?.click();};if(el.type==='checkbox')el.checked=originalInputs[j]?.checked;});});
 const mirror=document.createElement('table');mirror.className=table.className;mirror.style.cssText='width:'+rect.width+'px;table-layout:fixed;transform:translateX('+(rect.left-Math.max(clip.left,0))+'px)';mirror.append(head);headerMirror.replaceChildren(mirror);}headerMirror.firstElementChild.style.width=rect.width+'px';headerMirror.firstElementChild.style.transform='translateX('+(rect.left-Math.max(clip.left,0))+'px)';headerMirror.style.cssText='top:'+dockBottom+'px;left:'+Math.max(clip.left,0)+'px;width:'+Math.min(clip.width,innerWidth-Math.max(clip.left,0))+'px';
}
