function updateWeeklyRowDOM(id){const r=report(),e=r.entries[id];if(filter!=='all'&&(filter==='expired'||statusKey(e)!==filter)){render();return;}const row=[...document.querySelectorAll('tr[data-id]')].find(x=>x.dataset.id===id);if(!row){render();return;}row.className=statusKey(e)==='paid'?'paid':statusKey(e)==='deliver'?'waiting-delivery':statusKey(e)==='pay'?'waiting-payment':'';row.querySelectorAll('[data-entry]').forEach(input=>{const key=r.id+'|'+id+'|'+input.dataset.entry;if(document.activeElement===input||editDrafts.has(key))return;if(input.type==='checkbox')input.checked=!!e[input.dataset.entry];else input.value=e[input.dataset.entry]??'';});const allRows=rowsFor(state,r,year);const reviewed=document.querySelector('.review-count');if(reviewed)reviewed.textContent='ยืนยันแล้ว '+allRows.filter(x=>x.e.confirmed).length+'/'+allRows.length;const pending=document.querySelector('#pending-count');if(pending)pending.textContent=allRows.filter(x=>!x.e.confirmed).length||'';const summary=document.querySelector('.register-summary');if(summary){const template=document.createElement('template');template.innerHTML=weeklySummary(rowsFor(state,r,year));summary.replaceWith(template.content.firstElementChild);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=1;render();});}refreshReferenceMetrics({$,state,report,year,rowsFor});updateSaveStatus();restoreEdits();}
async function saveAllWeeklyDrafts(reportId=selected){
 const prefix=reportId+'|';
 const draftsToSave=[...editDrafts.entries()].filter(([k])=>k.startsWith(prefix));
 if(!draftsToSave.length)return;
 const r=state.reports.find(x=>x.id===reportId);
 if(!r)throw Error('ไม่พบรายงานที่เลือก');
 const patches={};
 for(const [key,draft] of draftsToSave){
  patches[draft.id]??={};
  patches[draft.id][draft.k]=draft.value;
 }
 if(r.locked){
  for(const [pid,patch] of Object.entries(patches)){
   const prev=previousEntry(r,pid)||{actual:0};
   const current={...(r.entries[pid]||{}),...patch};
   for(const [k,v] of Object.entries(patch)){
    applyWeeklyAutoRules(current,k,v,r,prev);
   }
   if(patch.weekly!==undefined&&patch.actual===undefined)patch.actual=current.actual;
   else if(patch.actual!==undefined&&patch.weekly===undefined)patch.weekly=current.weekly;
   if(current.payment!==undefined)patch.payment=current.payment;
   if(current.paymentDate!==undefined)patch.paymentDate=current.paymentDate;
   if(current.note!==undefined)patch.note=current.note;
  }
  await saveAmendment(reportId,patches);
 }else{
  await mutate('บันทึกผลงานรายสัปดาห์ '+Object.keys(patches).length+' รายการ',s=>{
   const rep=s.reports.find(x=>x.id===reportId);
   if(!rep||rep.locked)throw Error('รายงานถูกปิดแล้ว');
   for(const [pid,patch] of Object.entries(patches)){
    const e=rep.entries[pid];
    if(!e)continue;
    const prev=previousEntry(rep,pid)||{actual:0};
    for(const [k,v] of Object.entries(patch)){
     e[k]=v;
     applyWeeklyAutoRules(e,k,v,rep,prev);
    }
    validateDates(e);
    if(!('confirmed' in patch))e.confirmed=false;
    validateEntry(e,prev);
    const dateSyncKeys=Object.keys(patch).filter(k=>['note','payment','paymentDate','deliveryDate','acceptanceDate'].includes(k));
    if(dateSyncKeys.length){
     const keys=dateSyncKeys.includes('payment')?[...new Set([...dateSyncKeys,'paymentDate','payment','note'])]:dateSyncKeys;
     syncContractDates(s,pid,e,keys.filter(key=>!['note','payment'].includes(key)||!s.reports.some(later=>later.end>rep.end&&later.entries?.[pid])));
    }
   }
  });
 }
 for(const [key,draft] of draftsToSave)if(editDrafts.get(key)===draft)editDrafts.delete(key);
 persistEdits();
 if(view==='weekly'&&selected===reportId)render();
 else restoreEdits();
 updateSaveStatus();
 toast('บันทึกข้อมูลที่แก้ไขแล้ว ('+draftsToSave.length+' ช่อง)');
}
async function submitWeeklyEdit(reportId,id,k,value){const key=reportId+'|'+id+'|'+k,token=uid();editDrafts.set(key,{reportId,id,k,value,token});persistEdits();try{if(state.reports.find(r=>r.id===reportId)?.locked){const patch={[k]:value},r=state.reports.find(r=>r.id===reportId),prev=previousEntry(r,id)||{actual:0};const e={...(r.entries[id]||{}),[k]:value};applyWeeklyAutoRules(e,k,value,r,prev);if(k==='weekly')patch.actual=e.actual;if(k==='actual')patch.weekly=e.weekly;if(e.payment!==r.entries[id]?.payment)patch.payment=e.payment;if(e.paymentDate!==r.entries[id]?.paymentDate)patch.paymentDate=e.paymentDate;if(e.note!==r.entries[id]?.note)patch.note=e.note;await saveAmendment(reportId,{[id]:patch},{inlineId:id});}else await mutate('อัปเดตผลงาน '+id,s=>{const r=s.reports.find(x=>x.id===reportId);if(r.locked)throw Error('รายงานถูกปิดแล้ว');const e=r.entries[id];e[k]=value;const prev=previousEntry(r,id);applyWeeklyAutoRules(e,k,value,r,prev);validateDates(e);if(k!=='confirmed')e.confirmed=false;if(['weekly','actual','confirmed','payment','paymentDate'].includes(k))validateEntry(e,prev||{actual:0});else validateEntry(e);if(['note','payment','paymentDate','deliveryDate','acceptanceDate'].includes(k))syncContractDates(s,id,e,(k==='payment'?['paymentDate','payment','note']:[k]).filter(key=>!['note','payment'].includes(key)||!s.reports.some(later=>later.end>r.end&&later.entries?.[id])));},undefined,undefined,{reportId,id});if(editDrafts.get(key)?.token===token)editDrafts.delete(key);['payment','paymentDate','note','actual','weekly'].forEach(f=>{const compKey=reportId+'|'+id+'|'+f;if(editDrafts.get(compKey)?.token===token)editDrafts.delete(compKey);});persistEdits();if(view==='weekly'&&selected===reportId)updateWeeklyRowDOM(id);else restoreEdits();}catch(e){if(editDrafts.get(key)?.token===token)editDrafts.get(key).error=e.message;persistEdits();toast(e.message,true);restoreEdits();}}
