 const paint=()=>{const links=workCodeBudgetLinks(state),nodes=DOH_WORK_CATALOG.nodes.filter(n=>!n.id.endsWith('-admin')),list=nodes.filter(n=>{const p=workCodePath(n.code),linked=links.filter(l=>l.code===n.code);return(!query||[n.code,n.name].join(' ').includes(query))&&(!project||p.project?.id===project)&&(!activity||p.activity?.id===activity)&&(!account||(account==='unlinked'?!linked.length:linked.some(l=>l.budgetAccountId===account)));}),max=Math.max(1,Math.ceil(list.length/25));pageNo=Math.min(max,pageNo);$('.work-code-reference tbody').innerHTML=list.slice((pageNo-1)*25,pageNo*25).map(n=>{const path=workCodePath(n.code),dep=depreciationWorkCode(n.code),linked=links.filter(l=>l.code===n.code);return `<tr><td><strong>${esc(n.code)}</strong><br>${esc(n.name)}</td><td>${esc(path.project?.name||'–')}<br><small>${esc(path.activity?.name||'–')}</small></td><td>${esc(n.units.join(' / ')||'ไม่ได้ระบุในตาราง')}${n.unitSourceId?'<small>ตามกลุ่มรหัสงาน</small>':''}</td><td>${esc(dep)}${dep!==n.code?'<small>เชื่อมจากรหัสงานรอง</small>':''}${!depreciationSourceRule(dep)?'<small>ยังไม่พบในชีตค่าเสื่อม</small>':''}</td><td>${esc(linked.map(l=>state.budgetAccounts.find(b=>b.id===l.budgetAccountId)?.name).join(' / ')||'รอผูกบัญชี')}<br><button type="button" class="text-link" data-work-budget="${esc(n.code)}">ผูกบัญชีงบประมาณ</button></td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">ไม่พบข้อมูล ลองเปลี่ยนตัวกรอง</td></tr>';$('#work-catalog-count').textContent=list.length+' รายการ · หน้า '+pageNo+' / '+max;$('#work-catalog-prev').disabled=pageNo===1;$('#work-catalog-next').disabled=pageNo===max;$$('[data-work-budget]').forEach(b=>b.onclick=()=>workBudgetDialog(b.dataset.workBudget));};
