async function loadWorkspace(scope){
 const cachedState=state;
 const data=await cloud.loadCloud({...scope||{funding,year},screen:true});if(!data)return data;
 const jobs=[];
 if(data.referenceDeferred)jobs.push((async()=>{let cached;try{cached=JSON.parse(localStorage.getItem('pn-weekly-branding')||'null');}catch{}const branding=await cloud.loadBrandingCloud(cached?.hash),asset=branding?.notModified?cached:branding;if(asset&&typeof asset.logo==='string'){data.settings.logo=asset.logo;try{localStorage.setItem('pn-weekly-branding',JSON.stringify(asset));}catch{}}})());
 const r=data.loadedScope&&data.reports.find(r=>r.id===data.loadedScope.reportId);
 if(r?.locked&&Object.keys(r.entries||{}).length&&!Object.keys(r.snapshots||{}).length)jobs.push((async()=>{const detail=reusableReportDetail(data,cachedState)||await cloud.loadDetailCloud(r.id);if(!detail?.report||detail.revision!==data.revision)throw Error('ข้อมูลเปลี่ยนระหว่างโหลดรายงาน กรุณาโหลดล่าสุดอีกครั้ง');data.reports=data.reports.map(x=>x.id===r.id?detail.report:x);data.loadedScope={...data.loadedScope,previousEntries:detail.previousEntries||data.loadedScope.previousEntries||{}};})());
 const results=await Promise.allSettled(jobs);const failed=results.find(result=>result.status==='rejected');if(failed)throw failed.reason;
 data.importHistoryDeferred=true;if(!data.contractors){normalizeState(data);const result=await cloud.saveCloud(data,data.revision||0);data.revision=result.revision;}return data;
}

