function syncDatesToEntry(e,r,before={}){for(const [target,key]of [['note','note'],['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate'],['payment','payment']])if(r[key]!==before[key])e[target]=r[key]||'';if(e.payment==='เบิกจ่ายแล้ว'){if(!e.paymentDate)throw Error('รายงานฉบับร่างที่เบิกจ่ายแล้วต้องมีวันที่เบิกจ่าย');e.note=paymentNote(e);}}
function bindRegistryMasters(){const form=$('#contract-form');const inputFor=key=>form.querySelector(`[data-master-key="${key}"]`);const refresh=()=>{const code=state.workCodes.find(x=>x.name===inputFor('workCodes').value.trim()),type=state.workTypes.find(x=>x.name===inputFor('workTypes').value.trim());$$('#contract-form [data-master-key]').forEach(input=>{const key=input.dataset.masterKey;let rows=state[key].filter(x=>!x.deletedAt);if(key==='workNames')rows=rows.filter(x=>(!type||x.typeId===type.id)&&(!code||x.codeIds?.includes(code.id)));const text=input.value.trim();$('#registry-list-'+key).innerHTML=rows.filter(x=>!text||x.name.toLowerCase().includes(text.toLowerCase())).map(x=>`<option value="${esc(x.name)}">`).join('');form.querySelector(`[data-registry-add-master="${key}"]`).hidden=!text||state[key].some(x=>x.name===text&&!x.archived);});};
 $$('#contract-form [data-master-key]').forEach(input=>{input.oninput=refresh;input.onchange=()=>{if(input.dataset.masterKey==='workCodes'){const code=state.workCodes.find(x=>x.name===input.value.trim()),jobs=state.workNames.filter(x=>!x.archived&&x.codeIds?.includes(code?.id));if(jobs.length===1){inputFor('workNames').value=jobs[0].name;inputFor('workTypes').value=state.workTypes.find(x=>x.id===jobs[0].typeId)?.name||inputFor('workTypes').value;}}refresh();};});
 $$('#contract-form [data-registry-add-master]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const key=b.dataset.registryAddMaster,input=inputFor(key),name=input.value.trim();await mutate('เพิ่มรายการพื้นฐาน '+name,s=>{if(!name||s[key].some(x=>x.name===name&&!x.archived))throw Error('ชื่อว่างหรือมีอยู่แล้ว');const archivedItem=s[key].find(x=>x.name===name&&x.archived);if(archivedItem){archivedItem.archived=false;return;}const item={id:key.toUpperCase()+'-'+uid(),name,archived:false};if(key==='workNames'){item.typeId=s.workTypes.find(x=>x.name===inputFor('workTypes').value.trim())?.id||'';const code=s.workCodes.find(x=>x.name===inputFor('workCodes').value.trim());if(!code)throw Error('กรุณาเลือกรหัสงานก่อนเพิ่มชื่องาน');if(s.workNames.some(w=>w.codeIds?.includes(code.id)))throw Error('รหัสงานนี้จับคู่กับชื่องานอื่นแล้ว');item.codeIds=[code.id];}s[key].push(item);});refresh();input.focus();}catch(e){showFormError(form,e.message);}finally{b.disabled=false;}});refresh();}
async function ensureFirstWeekly(){if(view!=='weekly')return;const found=state.reports.find(r=>reportMatchesScope(state,r,year,funding));selected=found?.id;}
function weeklySummary(rows){const allCount=rows.length,ongoingCount=rows.filter(x=>statusKey(x.e)==='ongoing').length,deliverCount=rows.filter(x=>statusKey(x.e)==='deliver').length,payCount=rows.filter(x=>statusKey(x.e)==='pay').length,paidCount=rows.filter(x=>statusKey(x.e)==='paid').length,expiredCount=rows.filter(x=>weeklyExpired(x.p,x.e,report().reference||report().end)).length;const pct=count=>allCount?((count/allCount)*100).toFixed(1):'0.0';const cards=[{key:'all',label:'ทั้งหมด',count:allCount,sub:'สัญญาในรายงานรอบนี้',dot:'dot-emerald',cardClass:'card-all'},{key:'ongoing',label:'กำลังดำเนินการ',count:ongoingCount,sub:'อยู่ระหว่างการก่อสร้าง',dot:'dot-amber',cardClass:'card-ongoing'},{key:'deliver',label:'รอส่งมอบงาน',count:deliverCount,sub:'งานแล้วเสร็จ รอส่งมอบ',dot:'dot-gold',cardClass:'card-deliver'},{key:'pay',label:'รอเบิกจ่าย',count:payCount,sub:'ตรวจรับงานงวดสุดท้าย',dot:'dot-blue',cardClass:'card-pay'},{key:'paid',label:'เบิกจ่ายแล้ว',count:paidCount,sub:`เสร็จสิ้นสมบูรณ์ ${pct(paidCount)}%`,dot:'dot-emerald',cardClass:'card-paid',progress:pct(paidCount)},{key:'expired',label:'หมดอายุ · ยังดำเนินการ',count:expiredCount,sub:'ต้องเร่งรัดและติดตาม',dot:'dot-red',cardClass:'card-expired',progress:pct(expiredCount)}];return `<section class="register-summary weekly-summary" aria-label="สรุปสถานะสัญญา"><div class="summary-items weekly-bento-grid">${cards.map(c=>`<button type="button" data-filter="${c.key}" class="summary-count weekly-bento-card ${c.cardClass} status-${c.key} ${filter===c.key?'selected':''}" aria-label="${c.label} ${c.count} สัญญา"><div class="bento-top"><span class="bento-title">${c.label}</span><span class="bento-dot ${c.dot}"></span></div><div class="bento-body"><strong class="stat-number bento-number">${c.count.toLocaleString('th-TH')}</strong></div><div class="bento-foot"><span class="bento-subtext">${c.sub}</span>${c.progress!==undefined?`<div class="bento-progress-track"><div class="bento-progress-fill" style="width:${c.progress}%"></div></div>`:''}</div></button>`).join('')}</div></section>`;}
function contractDatesDialog(pid){const r=report(),saved=r.entries[pid],reg=state.contractRegistry.find(x=>x.projectId===pid),e={...saved,...Object.fromEntries([['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate']].map(([k,rk])=>[k,reg?.[rk]||saved[k]||'']))},p=projectAt(state,r,pid);modal('วันที่ส่งมอบ ตรวจรับ และเบิกจ่าย · '+p.contract,`<form><div class="form-grid">${field('วันส่งมอบงาน','deliveryDate',e.deliveryDate||'','date')}${field('วันตรวจรับงาน','acceptanceDate',e.acceptanceDate||'','date')}${field('วันที่เบิกจ่าย','paymentDate',e.paymentDate||'','date',e.payment==='เบิกจ่ายแล้ว'?'required':'')}</div>${buttons('บันทึกวันที่')}</form>`,async f=>{const patch=contractDatePatch(e,Object.fromEntries(['deliveryDate','acceptanceDate','paymentDate'].map(k=>[k,String(f.get(k)||'')])));if(!Object.keys(patch).length)throw Error('ยังไม่มีข้อมูลเปลี่ยนแปลง');validateDates({...e,...patch});if(r.locked)await saveAmendment(r.id,{[pid]:patch});else await mutate('บันทึกวันที่สัญญา',s=>{const entry=s.reports.find(x=>x.id===r.id).entries[pid];Object.assign(entry,patch);if(entry.payment==='เบิกจ่ายแล้ว')entry.note=paymentNote(entry);entry.confirmed=false;syncContractDates(s,pid,entry,[...Object.keys(patch),...(entry.payment==='เบิกจ่ายแล้ว'?['note']:[])]);});});}
function extensionRowsHTML(r){const rows=r.extensions||[];return `<section class="registry-section extension-records"><h3>บันทึกการขยาย / ลดอายุสัญญา</h3><div class="table-scroll"><table><thead><tr><th>ครั้งที่</th><th>สิ้นสุดเดิม</th><th>ประเภท</th><th>จำนวนวัน</th><th>สิ้นสุดหลังปรับ</th><th>จัดการ</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${x.sequence||i+1}</td><td>${fmt(x.previousEnd||'')}</td><td>${x.type==='reduce'||x.type==='ลด'?'ลด':'ขยาย'}</td><td>${x.days}</td><td>${fmt(x.end||'')}</td><td><button type="button" class="btn" data-edit-extension="${x.id}">แก้ไข</button> <button type="button" class="btn danger" data-delete-extension="${x.id}">ลบ</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีบันทึกการปรับอายุสัญญา</td></tr>'}</tbody></table></div><button type="button" class="btn" id="registry-extension">+ เพิ่มรายการ</button></section>`;}
